Here's a sample C++ program that reads a text file line by line, counts the number of occurrences of a specific word, and outputs the result:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

bool caseInsensitiveCompare(string a, string b) {
    transform(a.begin(), a.end(), a.begin(), ::tolower);
    transform(b.begin(), b.end(), b.begin(), ::tolower);
    return a < b;
}

int countWordOccurrences(const string& fileName, const string& wordToCount) {
    int count = 0;
    string line;
    ifstream inputFile(fileName);

    if (!inputFile.is_open()) {
        cerr << "Error: Cannot open file " << fileName << endl;
        return -1;
    }

    while (getline(inputFile, line)) {
        vector<string> words = split(line);
        sort(words.begin(), words.end(), caseInsensitiveCompare);
        vector<string>::iterator it = find(words.begin(), words.end(), wordToCount);
        if (it != words.end()) {
            count++;
        }
    }

    inputFile.close();
    return count;
}

vector<string> split(const string& str) {
    vector<string> tokens;
    size_t start = 0, end = 0;
    while ((end = str.find(" ", start)) != string::npos) {
        tokens.push_back(str.substr(start, end - start));
        start = end + 1;
    }
    tokens.push_back(str.substr(start));
